noDrag();
setTitle('IRC Terminal');
setPortCount(1, 1);

let nickname = 'Guest';
let currentInput = '';
let messageHistory = [
  { type: 'system', text: '--- TERMINAL INITIALIZED ---' },
  { type: 'system', text: 'set name with :name <nick>' },
];
let cursorState = true;
setInterval(() => cursorState = !cursorState, 500);

// Handle message reception
recv((data) => {
  if (data && typeof data === 'object' && data.type === 'setName') {
    nickname = data.value;
    messageHistory.push({ type: 'system', text: `>> Nickname changed to: ${nickname}` });
  } else if (typeof data === 'string') {
    messageHistory.push({ type: 'remote', text: data });
  }
});

onKeyDown(e => {
  if (e.key === 'Enter') {
    const trimmed = currentInput.trim();
    if (trimmed.startsWith(':name ')) {
      const newName = trimmed.split(' ')[1];
      if (newName) {
        nickname = newName;
        messageHistory.push({ type: 'system', text: `>> Name set to: ${nickname}` });
      }
    } else if (currentInput.length > 0) {
      const formatted = `<${nickname}> ${currentInput}`;
      send(formatted);
      messageHistory.push({ type: 'local', text: formatted });
    }
    currentInput = '';
  } else if (e.key === 'Backspace') {
    currentInput = currentInput.slice(0, -1);
  } else if (e.key.length === 1) {
    currentInput += e.key;
  }
});

function draw() {
  // CRT Background with slight pulse if audio is present
  const analysis = fft();
  const pulse = analysis ? analysis.avg * 50 : 0;

  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0, 0, width, height);

  // Big Monospace Font
  const fontSize = 36;
  ctx.font = `bold ${fontSize}px monospace`;
  ctx.textBaseline = 'bottom';

  // CRT Glow Effect
  ctx.shadowBlur = 15;

  // Calculate layout
  const margin = 30;
  const lineHeight = fontSize + 10;
  let currentY = height - margin;

  // Draw Current Input Line
  ctx.fillStyle = '#00ff41';
  ctx.shadowColor = '#00ff41';
  const prompt = `[${nickname}]> `;
  const cursor = cursorState ? '_' : ' ';
  ctx.fillText(prompt + currentInput + cursor, margin, currentY);

  // Draw History (Scrolling upwards)
  currentY -= lineHeight;
  for (let i = messageHistory.length - 1; i >= 0; i--) {
    const msg = messageHistory[i];

    if (msg.type === 'local') {
      ctx.fillStyle = '#4ade80';
      ctx.shadowColor = '#4ade80';
    } else if (msg.type === 'remote') {
      ctx.fillStyle = '#3b82f6';
      ctx.shadowColor = '#3b82f6';
    } else {
      ctx.fillStyle = '#94a3b8';
      ctx.shadowColor = '#94a3b8';
    }

    ctx.fillText(msg.text, margin, currentY);
    currentY -= lineHeight;
    if (currentY < -fontSize) break;
  }

  // Scanlines Overlay
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255, 255, 255, 0.03)';
  for (let i = 0; i < height; i += 4) {
    ctx.fillRect(0, i, width, 1);
  }

  // Vignette
  const grd = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, width/1.5);
  grd.addColorStop(0, 'rgba(0,0,0,0)');
  grd.addColorStop(1, 'rgba(0,0,0,0.4)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, width, height);

  requestAnimationFrame(draw);
}

draw();
